                                    <MessageCircle size={13} /> WhatsApp
                                </a>
                            )}
                            <button onClick={() => handleStageChange('test_drive_booked')}
                                className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-bold transition-all hover:opacity-90"
