import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
    Users, Search, Filter, Tag as TagIcon, CreditCard, ChevronRight, X, UserCircle, Car, Calendar, Star, MessageSquare, CheckCircle, Wrench
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000';

function getTierStyle(points) {
    if (points >= 1000) return 'text-[#E5E4E2] bg-gradient-to-r from-gray-300 to-gray-400';
    if (points >= 500) return 'text-yellow-600 bg-gradient-to-r from-yellow-300 to-yellow-500';
    if (points >= 200) return 'text-gray-300 bg-gradient-to-r from-gray-400 to-gray-500';
    return 'text-orange-400 bg-gradient-to-r from-orange-300 to-orange-500'; // bronze fallback
}
function getTierName(points) {
    if (points >= 1000) return 'Platinum';
    if (points >= 500) return 'Gold';
    if (points >= 200) return 'Silver';
    return 'Bronze';
}

export default function Customers() {
    const { user } = useAuth();
    const [customers, setCustomers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedCustomer, setSelectedCustomer] = useState(null);
    const [newTagVal, setNewTagVal] = useState('');

    useEffect(() => { loadCustomers(); }, [searchQuery]);

    const loadCustomers = async () => {
        setLoading(true);
        try {
            const res = await axios.get(`${API_URL}/api/customers`, { params: { q: searchQuery } });
            setCustomers(res.data);
        } catch (e) { console.error('Error fetching customers', e); }
        setLoading(false);
    };

    const addTag = async (e) => {
        if (e.key === 'Enter' && newTagVal.trim() && selectedCustomer) {
            e.preventDefault();
            const tagStr = newTagVal.trim();
            const currentTags = selectedCustomer.tags || [];
            if (currentTags.includes(tagStr)) { setNewTagVal(''); return; }

            const newTags = [...currentTags, tagStr];
            try {
                const res = await axios.patch(`${API_URL}/api/customers/${selectedCustomer.id}/tags`, { tags: newTags });
                setSelectedCustomer(res.data);
                // Background update list
                setCustomers(prev => prev.map(c => c.id === res.data.id ? res.data : c));
            } catch (err) { alert('Failed to add tag'); }
            setNewTagVal('');
        }
    };

    const removeTag = async (tagToRemove) => {
        if (!selectedCustomer) return;
        const newTags = selectedCustomer.tags.filter(t => t !== tagToRemove);
        try {
            const res = await axios.patch(`${API_URL}/api/customers/${selectedCustomer.id}/tags`, { tags: newTags });
            setSelectedCustomer(res.data);
            setCustomers(prev => prev.map(c => c.id === res.data.id ? res.data : c));
        } catch (err) { alert('Failed to remove tag'); }
    };

    return (
        <div className="flex flex-col h-screen bg-[#0A0F1E] text-white">
            <header className="px-8 py-5 flex items-center justify-between sticky top-0 z-10"
                style={{ background: 'rgba(10,15,30,0.85)', backdropFilter: 'blur(20px)', borderBottom: '1px solid rgba(201,168,76,0.08)' }}>
                <div className="flex items-center gap-4">
                    <div className="p-2.5 rounded-xl bg-orange-500/10 border border-orange-500/20 text-[#C9A84C]">
                        <Users size={20} />
                    </div>
                    <div>
                        <p className="text-[9px] font-black uppercase tracking-[0.3em] mb-0.5" style={{ color: 'rgba(201,168,76,0.4)' }}>Module</p>
                        <h1 className="font-outfit font-black text-xl text-white">Customer Database</h1>
                    </div>
                </div>

                <div className="relative w-72">
                    <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/30" />
                    <input type="text" placeholder="Search by name, phone, or vehicle..."
                        value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-3 py-2 text-xs focus:border-[#C9A84C] outline-none text-white transition-all" />
                </div>
            </header>

            <div className="flex-1 overflow-auto p-8 relative">
                {loading ? <p className="text-white/30 text-xs text-center mt-10">Loading database...</p> : (
                    <div className="grid grid-cols-1 gap-4">
                        {customers.map(c => (
                            <div key={c.id} onClick={() => setSelectedCustomer(c)}
                                className="bg-white/5 border border-white/5 p-4 rounded-xl flex items-center justify-between cursor-pointer hover:bg-white/10 transition-colors">
                                <div className="flex items-center gap-4 w-1/3">
                                    <div className="w-10 h-10 rounded-full bg-[#C9A84C]/10 text-[#C9A84C] flex items-center justify-center font-bold text-sm">
                                        {c.first_name[0]}{c.last_name[0]}
                                    </div>
                                    <div>
                                        <p className="font-bold text-white text-sm">{c.first_name} {c.last_name}</p>
                                        <p className="text-[10px] text-white/50">{c.phone}</p>
                                    </div>
                                </div>
                                <div className="w-1/4 text-xs text-white/60">
                                    <p className="font-bold text-white mb-0.5">{c.vehicle_owned_make} {c.vehicle_owned_model}</p>
                                    <p className="text-[10px]">Purchased: {new Date(c.purchase_date).toLocaleDateString()}</p>
                                </div>
                                <div className="w-1/4 flex gap-2 flex-wrap">
                                    {c.tags?.map((t, i) => (
                                        <span key={i} className="px-2 py-0.5 rounded text-[9px] font-bold uppercase border border-white/10 text-white/60 bg-black/20">{t}</span>
                                    ))}
                                </div>
                                <div className="w-1/6 text-right">
                                    <p className="text-[10px] uppercase font-black tracking-widest text-[#C9A84C]">{getTierName(c.loyalty_points)} Tier</p>
                                    <p className="text-[10px] text-white/40 mt-1">NPS: {c.nps_score ? <span className="font-bold text-green-400">{c.nps_score}/10</span> : '-'}</p>
                                </div>
                            </div>
                        ))}
                        {customers.length === 0 && <p className="text-center text-white/30 text-xs">No customers matched your query.</p>}
                    </div>
                )}
            </div>

            {/* ── Slide-Over: Customer Profile ── */}
            {selectedCustomer && (
                <div className="absolute inset-0 bg-black/60 backdrop-blur-sm z-50 flex justify-end">
                    <div className="w-[550px] h-full shadow-2xl overflow-y-auto anim-slide-left"
                        style={{ background: '#0D1526', borderLeft: '1px solid rgba(201,168,76,0.15)' }}>
                        <div className="p-6 border-b border-white/5 flex justify-between items-start sticky top-0 bg-[#0D1526] z-10">
                            <div className="flex gap-4 items-center">
                                <div className="w-16 h-16 rounded-full bg-[#C9A84C]/20 text-[#C9A84C] border border-[#C9A84C]/30 flex items-center justify-center font-black text-xl">
                                    {selectedCustomer.first_name[0]}{selectedCustomer.last_name[0]}
                                </div>
                                <div>
                                    <h2 className="font-outfit font-black text-2xl">{selectedCustomer.first_name} {selectedCustomer.last_name}</h2>
                                    <div className="flex items-center gap-3 text-xs text-white/60 mt-1">
                                        <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase shadow-sm ${getTierStyle(selectedCustomer.loyalty_points)}`}>
                                            {getTierName(selectedCustomer.loyalty_points)} Tier
                                        </span>
                                        <span>{selectedCustomer.loyalty_points} Points</span>
                                        {selectedCustomer.nps_score && (
                                            <span className="flex items-center font-bold text-green-400 gap-1"><Star size={10} fill="currentColor" /> NPS {selectedCustomer.nps_score}/10</span>
                                        )}
                                    </div>
                                </div>
                            </div>
                            <button onClick={() => setSelectedCustomer(null)} className="p-2 text-white/50 hover:bg-white/10 rounded-full"><X size={20} /></button>
                        </div>

                        <div className="p-6 space-y-8">
                            {/* Contact Details */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="bg-white/5 p-4 rounded-xl border border-white/5">
                                    <p className="text-[10px] uppercase font-bold text-white/30 mb-1">Email</p>
                                    <p className="text-sm font-bold truncate">{selectedCustomer.email || 'N/A'}</p>
                                </div>
                                <div className="bg-white/5 p-4 rounded-xl border border-white/5">
                                    <p className="text-[10px] uppercase font-bold text-white/30 mb-1">Phone / WhatsApp</p>
                                    <p className="text-sm font-bold truncate">{selectedCustomer.phone || selectedCustomer.whatsapp_number}</p>
                                </div>
                            </div>

                            {/* Tags Configuration */}
                            <div>
                                <h3 className="text-xs uppercase font-black text-white/40 tracking-widest mb-3 flex items-center gap-2"><TagIcon size={14} /> Segmentation Tags</h3>
                                <div className="flex flex-wrap gap-2 items-center">
                                    {selectedCustomer.tags?.map((t, i) => (
                                        <div key={i} className="flex flex-wrap items-center bg-[#C9A84C]/10 border border-[#C9A84C]/30 text-[#C9A84C] px-2.5 py-1 rounded text-xs font-bold gap-2">
                                            {t}
                                            <button onClick={() => removeTag(t)} className="hover:text-white transition-colors"><X size={10} /></button>
                                        </div>
                                    ))}
                                    <input type="text" placeholder="Type tag and press Enter..." value={newTagVal}
                                        onChange={e => setNewTagVal(e.target.value)} onKeyDown={addTag}
                                        className="bg-transparent border border-dashed border-white/20 text-xs p-1.5 rounded outline-none focus:border-white/50 text-white w-48" />
                                </div>
                            </div>

                            {/* Current Vehicle */}
                            {selectedCustomer.vehicle_owned_make && (
                                <div>
                                    <h3 className="text-xs uppercase font-black text-white/40 tracking-widest mb-3 flex items-center gap-2"><Car size={14} /> Vehicle Ownership</h3>
                                    <div className="bg-gradient-to-r from-white/5 to-transparent border-l-2 border-[#C9A84C] p-4 rounded-r-xl relative overflow-hidden">
                                        <Car size={100} className="absolute right-0 bottom-0 text-white/5 opacity-50 transform translate-x-4" />
                                        <p className="font-outfit font-black text-lg mb-1">{selectedCustomer.vehicle_owned_year} {selectedCustomer.vehicle_owned_make} {selectedCustomer.vehicle_owned_model}</p>
                                        <div className="flex gap-4 text-xs font-mono text-white/50 mt-2">
                                            <p>REG: <span className="text-white">{selectedCustomer.registration}</span></p>
                                            <p>VIN: <span className="text-white">{selectedCustomer.vin}</span></p>
                                        </div>
                                        <p className="text-[10px] uppercase text-white/40 font-bold mt-4">Delivered: {new Date(selectedCustomer.purchase_date).toLocaleDateString()}</p>
                                    </div>
                                </div>
                            )}

                            {/* Interaction Timeline */}
                            <div>
                                <h3 className="text-xs uppercase font-black text-white/40 tracking-widest mb-4 flex items-center gap-2"><Calendar size={14} /> Timeline History</h3>
                                <div className="border-l border-white/10 ml-4 space-y-6">
                                    {/* Mocking generic unified timeline structure */}
                                    <div className="relative pl-6">
                                        <div className="absolute left-[-11px] top-0.5 bg-green-500 rounded-full p-1 border-2 border-[#0D1526] text-[#0D1526]"><CheckCircle size={12} /></div>
                                        <p className="text-[10px] text-white/40 font-bold mb-0.5">Today</p>
                                        <p className="text-sm font-bold text-white">Triggered Automated NPS Survey via WhatsApp</p>
                                    </div>
                                    <div className="relative pl-6">
                                        <div className="absolute left-[-11px] top-0.5 bg-blue-500 rounded-full p-1 border-2 border-[#0D1526] text-[#0D1526]"><Wrench size={12} /></div>
                                        <p className="text-[10px] text-white/40 font-bold mb-0.5">14 Feb 2026</p>
                                        <p className="text-sm font-bold text-white">Completed Minor Service (15,000km)</p>
                                    </div>
                                    <div className="relative pl-6">
                                        <div className="absolute left-[-11px] top-0.5 bg-[#C9A84C] rounded-full p-1 border-2 border-[#0D1526] text-[#0D1526]"><CreditCard size={12} /></div>
                                        <p className="text-[10px] text-white/40 font-bold mb-0.5">20 Jan 2025</p>
                                        <p className="text-sm font-bold text-white">Deal Delivered. Vehicle Sold!</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Mail, ArrowRight, ArrowLeft, AlertCircle, CheckCircle2 } from 'lucide-react';

const ForgotPassword = () => {
    const [email, setEmail] = useState('');
    const [sent, setSent] = useState(false);
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!email.trim()) { setError('Email is required.'); return; }
        setError('');
        setIsLoading(true);

        try {
            const res = await fetch(
                `${import.meta.env.VITE_API_URL || 'http://localhost:3000'}/auth/forgot-password`,
                {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ email }),
                }
            );
            setSent(true);
        } catch {
            setError('Network error. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center p-6" style={{ background: '#060A14' }}>
            <div className="absolute inset-0 pointer-events-none"
                style={{ background: 'radial-gradient(ellipse 60% 40% at 50% 0%, rgba(201,168,76,0.05), transparent)' }} />

            <div className="w-full max-w-md anim-fade-up">
                {/* Brand */}
                <div className="flex items-center gap-3 mb-8 justify-center">
                    <div className="h-9 w-9 rounded-xl flex items-center justify-center font-outfit font-black text-sm"
                        style={{ background: 'linear-gradient(135deg,rgba(201,168,76,0.2),rgba(201,168,76,0.07))', border: '1px solid rgba(201,168,76,0.3)', color: '#C9A84C' }}>
                        KA
                    </div>
                    <h1 className="font-outfit font-black text-xl">
                        <span className="text-white">KENGAN</span><span className="gold-text">AUTO</span>
                    </h1>
                </div>

                <div className="rounded-3xl p-10"
                    style={{
                        background: 'linear-gradient(135deg, rgba(17,30,53,0.9) 0%, rgba(10,15,30,0.95) 100%)',
                        border: '1px solid rgba(201,168,76,0.15)',
                        boxShadow: '0 32px 80px rgba(0,0,0,0.6)',
                        backdropFilter: 'blur(20px)',
                    }}>

                    {!sent ? (
                        <>
                            <div className="mb-8">
                                <p className="text-[10px] font-black uppercase tracking-[0.3em] mb-2" style={{ color: 'rgba(201,168,76,0.5)' }}>
                                    Password Recovery
                                </p>
                                <h2 className="font-outfit font-black text-2xl text-white">Forgot your password?</h2>
                                <p className="text-sm mt-2" style={{ color: 'rgba(240,237,232,0.4)' }}>
                                    Enter your email and we'll send a reset link valid for 15 minutes.
                                </p>
                            </div>

                            {error && (
                                <div className="flex items-center gap-3 px-4 py-3 rounded-xl mb-6 text-sm font-medium"
                                    style={{ background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.2)', color: '#FCA5A5' }}>
                                    <AlertCircle size={16} />
                                    {error}
                                </div>
                            )}

                            <form onSubmit={handleSubmit} className="space-y-5">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-[0.2em] block" style={{ color: 'rgba(240,237,232,0.4)' }}>
                                        Email Address
                                    </label>
                                    <div className="relative">
                                        <Mail className="absolute left-4 top-1/2 -translate-y-1/2" size={16} style={{ color: 'rgba(201,168,76,0.4)' }} />
                                        <input type="email" value={email} onChange={e => setEmail(e.target.value)}
                                            placeholder="name@dealership.co.za" className="lux-input pl-11" required />
                                    </div>
                                </div>

                                <button type="submit" disabled={isLoading}
                                    className="w-full py-4 font-outfit font-black text-sm tracking-widest uppercase flex items-center justify-center gap-2 rounded-2xl transition-all disabled:opacity-60"
                                    style={{
                                        background: 'linear-gradient(135deg, #C9A84C 0%, #9A7830 100%)',
                                        color: '#0A0F1E',
                                        boxShadow: '0 8px 32px rgba(201,168,76,0.25)',
                                    }}>
                                    {isLoading ? 'Sending…' : (<>Send Reset Link <ArrowRight size={17} /></>)}
                                </button>
                            </form>
                        </>
                    ) : (
                        <div className="text-center space-y-6">
                            <div className="h-16 w-16 mx-auto rounded-2xl flex items-center justify-center"
                                style={{ background: 'rgba(74,222,128,0.1)', border: '1px solid rgba(74,222,128,0.25)' }}>
                                <CheckCircle2 size={28} style={{ color: '#4ADE80' }} />
                            </div>
                            <div>
                                <h2 className="font-outfit font-black text-2xl text-white mb-2">Check your inbox</h2>
                                <p className="text-sm" style={{ color: 'rgba(240,237,232,0.4)' }}>
                                    If <span className="font-bold text-white">{email}</span> is registered, a reset link has been sent. It expires in 15 minutes.
                                </p>
                            </div>
                        </div>
                    )}

                    <div className="mt-8 pt-6 text-center" style={{ borderTop: '1px solid rgba(201,168,76,0.08)' }}>
                        <Link to="/login"
                            className="inline-flex items-center gap-2 text-[11px] font-bold transition-colors"
                            style={{ color: 'rgba(201,168,76,0.5)' }}>
                            <ArrowLeft size={13} /> Back to Login
                        </Link>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ForgotPassword;

import React, { useEffect, useState } from 'react';
import axios from 'axios';
import {
    CheckCircle2,
    Code,
    ExternalLink,
    Facebook,
    Globe,
    Mail,
    MessageCircle,
    Send
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { PageShell, Surface } from '../components/PageShell';
import CollapsibleSection from '../components/CollapsibleSection';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000';

export default function Integrations() {
    const { token } = useAuth();
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [testStatus, setTestStatus] = useState({});

    useEffect(() => {
        loadSettings();
    }, []);

    const loadSettings = async () => {
        try {
            const res = await axios.get(`${API_URL}/api/integrations/settings`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setData(res.data.integrations);
        } catch (error) {
            console.error('Error fetching integrations:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleFacebookConnect = async () => {
        try {
            const res = await axios.post(`${API_URL}/api/integrations/facebook/oauth`, {}, {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.data.success) {
                loadSettings();
            }
        } catch (error) {
            console.error(error);
        }
    };

    const runGenericTest = async () => {
        setTestStatus((current) => ({ ...current, generic: 'Testing...' }));
        try {
            await axios.post(`${data.webhook_url}`, {
                customer_name: 'Test Webhook User',
                customer_phone: '+27820001111',
                vehicle_interest: 'Test Polo GTI',
                source: 'test_button'
            });
            setTestStatus((current) => ({ ...current, generic: 'Success' }));
            setTimeout(() => setTestStatus({}), 3000);
        } catch {
            setTestStatus((current) => ({ ...current, generic: 'Failed' }));
        }
    };

    if (loading) {
        return <div className="p-8 text-white">Loading integrations...</div>;
    }

    if (!data) {
        return <div className="p-8 text-white">Failed to load integrations.</div>;
    }

    const integrationCards = [
        {
            id: 'autotrader',
            name: 'AutoTrader.co.za',
            icon: Mail,
            iconColor: 'text-blue-400',
            status: data.autotrader.active ? 'Connected' : 'Offline',
            leads: data.autotrader.leads_this_month,
            summary: 'Marketplace enquiries flow into the CRM through the inbound parsing address.',
            detail: data.inbound_email,
            detailLabel: 'Lead forwarding email',
        },
        {
            id: 'cars_coza',
            name: 'Cars.co.za',
            icon: Mail,
            iconColor: 'text-red-400',
            status: data.cars_coza.active ? 'Connected' : 'Offline',
            leads: data.cars_coza.leads_this_month,
            summary: 'Direct inbound lead parsing for Cars.co.za enquiries.',
            detail: data.inbound_email,
            detailLabel: 'Lead forwarding email',
        },
        {
            id: 'facebook',
            name: 'Facebook Lead Ads',
            icon: Facebook,
            iconColor: 'text-blue-500',
            status: data.facebook.active ? 'Connected' : 'Not connected',
            leads: data.facebook.leads_this_month,
            summary: data.facebook.active ? `Linked to ${data.facebook.page_name}.` : 'Connect a page to sync Instant Form leads directly into the pipeline.',
            detail: data.facebook.active ? data.facebook.page_name : null,
            detailLabel: data.facebook.active ? 'Connected page' : null,
            action: !data.facebook.active ? (
                <button
                    onClick={handleFacebookConnect}
                    className="rounded-xl bg-[#1877F2] px-4 py-2.5 text-sm font-semibold text-white transition hover:opacity-90"
                >
                    Connect Facebook
                </button>
            ) : (
                <span className="inline-flex items-center gap-2 rounded-full bg-green-500/10 px-3 py-1.5 text-sm font-medium text-green-300">
                    <CheckCircle2 size={14} />
                    Live sync active
                </span>
            ),
        },
        {
            id: 'generic',
            name: 'Generic API Webhook',
            icon: Code,
            iconColor: 'text-emerald-400',
            status: 'Operational',
            leads: data.generic_webhook.leads_this_month,
            summary: 'Use this webhook for custom website forms or external lead sources.',
