import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Mail, MessageCircle, Smartphone, Clock, Eye, Send, ShieldAlert, CheckCircle2, ChevronDown, Bell } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000';

const ROLES = [
    { id: 'sales_exec', label: 'Sales Execs' },
    { id: 'sales_manager', label: 'Sales Managers' },
    { id: 'finance_manager', label: 'Finance Managers' },
    { id: 'service_advisor', label: 'Service Advisors' },
    { id: 'dealer_principal', label: 'Dealer Principal' },
    { id: 'customer', label: 'Customer' }
];

export default function NotificationSettings() {
    const { user, token } = useAuth();
    const [settings, setSettings] = useState(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    // Test modal state
    const [testModal, setTestModal] = useState(false);
    const [testPayload, setTestPayload] = useState({ channel: 'email', destination: '' });
    const [testStatus, setTestStatus] = useState('');

    useEffect(() => { loadSettings(); }, []);

    const loadSettings = async () => {
        try {
            const res = await axios.get(`${API_URL}/api/notifications/settings`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setSettings(res.data.settings);
        } catch (e) { console.error('Error fetching notification settings:', e); }
        setLoading(false);
    };

    const handleSave = async (updatedSettings) => {
        setSaving(true);
        try {
            await axios.put(`${API_URL}/api/notifications/settings`, updatedSettings, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setSettings(updatedSettings);
        } catch (e) { console.error('Error saving settings:', e); }
        setSaving(false);
    };

    const toggleChannelSetting = (channel, key) => {
        const newSet = JSON.parse(JSON.stringify(settings));
        newSet[channel][key].active = !newSet[channel][key].active;
        handleSave(newSet);
    };

    const toggleRole = (channel, key, roleId) => {
        const newSet = JSON.parse(JSON.stringify(settings));
        const currentRoles = newSet[channel][key].roles;
        if (currentRoles.includes(roleId)) {
            newSet[channel][key].roles = currentRoles.filter(r => r !== roleId);
        } else {
            newSet[channel][key].roles.push(roleId);
        }
        handleSave(newSet);
    };

    const handleHoursChange = (type, val) => {
        const newSet = JSON.parse(JSON.stringify(settings));
        newSet.hours[type] = val;
        handleSave(newSet);
    };

    const sendTestNotification = async () => {
        setTestStatus('Sending...');
        try {
            await axios.post(`${API_URL}/api/notifications/test`, testPayload, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setTestStatus('Dispatched Successfully');
            setTimeout(() => setTestModal(false), 2000);
        } catch (e) {
            setTestStatus('Failed to send');
        }
    };

    const previewTemplate = (templateKey) => {
        window.open(`${API_URL}/api/notifications/preview/${templateKey}`, '_blank');
    };

    if (loading || !settings) return <div className="p-8 text-[#C9A84C] font-black uppercase tracking-widest">Loading Routing Core...</div>;

    const renderCard = (channelName, icon, dataKey, definitions) => (
        <div className="bg-black/30 border border-white/5 rounded-2xl overflow-hidden mb-8">
            <div className="bg-white/5 px-6 py-4 flex items-center justify-between border-b border-white/5">
                <h3 className="font-outfit font-black text-white uppercase tracking-widest flex items-center gap-3">
                    {icon} {channelName} Triggers
                </h3>
            </div>
            <div className="divide-y divide-white/5">
                {definitions.map((def, i) => (
                    <div key={i} className="p-6 flex flex-col xl:flex-row gap-6 justify-between items-start xl:items-center hover:bg-white/5 transition-colors">
                        <div className="flex-1">
                            <h4 className="font-bold text-white mb-1 tracking-wider">{def.title}</h4>
                            <p className="text-[10px] text-white/50 uppercase font-black tracking-widest leading-relaxed max-w-lg">{def.desc}</p>
                        </div>

                        <div className="flex flex-col gap-3 min-w-[280px]">
                            {/* Role Selectors (Pills) */}
                            <div className="flex flex-wrap gap-1.5">
                                {ROLES.map(r => {
                                    const isSelected = settings[dataKey][def.key].roles.includes(r.id);
                                    // Make Customers locked for certain hard-coded routes? Simple UI: just toggle everything
                                    return (
                                        <button key={r.id} onClick={() => toggleRole(dataKey, def.key, r.id)}
                                            className={`px-2 py-1 text-[9px] uppercase font-bold tracking-widest rounded transition-all border
                                                ${isSelected ? 'bg-[#C9A84C]/20 border-[#C9A84C]/50 text-[#C9A84C]' : 'bg-transparent border-white/10 text-white/30 hover:text-white hover:border-white/30'}`}>
                                            {r.label}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>

                        <div className="flex items-center gap-4 shrink-0 mt-4 xl:mt-0">
                            {def.hasPreview && (
                                <button onClick={() => previewTemplate(def.key)} className="p-2 border border-white/10 text-white hover:text-[#3B82F6] hover:border-[#3B82F6]/50 rounded-xl transition-all" title="Preview Template">
                                    <Eye size={16} />
                                </button>
                            )}
                            <button onClick={() => toggleChannelSetting(dataKey, def.key)}
                                className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${settings[dataKey][def.key].active ? 'bg-[#C9A84C]' : 'bg-white/10'}`}>
                                <span className={`inline-block h-4 w-4 transform rounded-full bg-black transition-transform ${settings[dataKey][def.key].active ? 'translate-x-6' : 'translate-x-1'}`} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );

    return (
        <div className="p-8 max-w-7xl mx-auto text-white">

            <div className="flex justify-between items-end mb-8 pt-2 relative">
                <div>
                    <p className="text-[9px] font-black uppercase tracking-[0.3em] mb-1.5" style={{ color: 'rgba(201,168,76,0.6)' }}>Settings & Routing</p>
                    <h1 className="font-outfit font-black text-3xl text-white tracking-wide">Communication Triggers</h1>
                </div>
                <button onClick={() => setTestModal(true)} className="flex items-center gap-2 px-5 py-2.5 bg-blue-500 hover:bg-blue-600 text-white font-bold rounded-xl transition-colors shadow-lg shadow-blue-500/20 text-xs">
                    <Send size={14} /> Send Global Test
                </button>
            </div>

            {/* ROUTING HOURS LOCK */}
            <div className="bg-black/40 border border-[#C9A84C]/30 p-6 rounded-2xl mb-8 flex items-center justify-between">
                <div>
                    <h3 className="font-outfit font-black text-[#C9A84C] uppercase tracking-widest mb-1 flex items-center gap-2"><Clock size={16} /> Staff Silent Hours Routing</h3>
                    <p className="text-[10px] uppercase font-bold text-white/50 tracking-widest">During silent hours, WhatsApp triggers to staff will be suppressed or held in the dashboard queue.</p>
                </div>
                <div className="flex items-center gap-4">
                    <div className="flex flex-col">
                        <span className="text-[9px] uppercase font-bold text-white/40 mb-1 tracking-widest">Active From</span>
                        <input type="time" value={settings.hours.start} onChange={(e) => handleHoursChange('start', e.target.value)}
                            className="bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-[#C9A84C]" />
                    </div>
                    <span className="text-white/20 mt-4">—</span>
                    <div className="flex flex-col">
                        <span className="text-[9px] uppercase font-bold text-white/40 mb-1 tracking-widest">Active Until</span>
                        <input type="time" value={settings.hours.end} onChange={(e) => handleHoursChange('end', e.target.value)}
                            className="bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-[#C9A84C]" />
                    </div>
                </div>
            </div>

            {/* EMAIL DEFINITIONS */}
            {renderCard('Email', <Mail size={18} className="text-blue-400" />, 'email', [
                { key: 'new_lead', title: 'New Hot Lead Alert', desc: 'Dispatched when AI detects strong purchase intent.', hasPreview: true },
                { key: 'finance_app', title: 'Finance Application Received', desc: 'F&I module structured data payload notification.', hasPreview: false },
                { key: 'service_confirm', title: 'Service Booked & Confirmed', desc: 'Formal confirmation outlining date, location & required items.', hasPreview: false },
                { key: 'service_reminder', title: 'Service 48h Reminder Sequence', desc: 'Automated follow-up preventing no-shows.', hasPreview: false },
                { key: 'trade_in_offer', title: 'Trade-in Offer Dispatched', desc: 'Automated certificate of offer generation.', hasPreview: false },
                { key: 'deal_won', title: 'Deal Moved To Won', desc: 'Internal motivational dispatch alerting DP + Execs.', hasPreview: false },
                { key: 'weekly_summary', title: 'Automated Weekly KPI Summary', desc: 'Every Monday 08:00 AM snapshot reporting.', hasPreview: false },
                { key: 'monthly_report', title: '1st of Month BI Analytics', desc: 'Deep dive metrics dispatched automatically.', hasPreview: false }
            ])}

            {/* WHATSAPP DEFINITIONS */}
            {renderCard('WhatsApp (Via 360Dialog)', <MessageCircle size={18} className="text-green-400" />, 'whatsapp', [
                { key: 'hot_lead', title: 'Instant Lead Assignment', desc: 'Push directly to staff phones immediately when assigned.' },
                { key: 'customer_arrived', title: 'Service Customer Arrival', desc: 'Alerts Advisor when receptionist checks in the car.' },
                { key: 'vehicle_ready', title: 'Vehicle Ready For Collection', desc: 'Notifies customer directly with collection instructions.' },
                { key: 'finance_app', title: 'Credit App Urgent Alert', desc: 'Rapid alert pointing F&I manager into the system.' },
                { key: 'dp_daily_summary', title: 'Daily DP Overview', desc: 'Scheduled 5 PM total unit sales / bookings recap.' }
            ])}

            {/* SMS DEFINITIONS */}
            {renderCard('Fall-Back SMS (Clickatell)', <Smartphone size={18} className="text-orange-400" />, 'sms', [
                { key: 'service_confirm', title: 'Service Booking (No-WhatsApp)', desc: 'Standard SMS pushed if customer lacks WhatsApp.' },
                { key: 'service_reminder', title: 'Service 48h Reminder (No-WhatsApp)', desc: 'Standard SMS reminder payload.' },
                { key: 'finance_outcome', title: 'Finance Result Payload', desc: 'Shortened SMS alerting customer to check portals.' }
            ])}

            {/* MODAL: TEST SENDER */}
            {testModal && (
                <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-[#0A0F1E] border border-white/10 p-8 rounded-2xl w-full max-w-md relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-emerald-500" />
                        <h2 className="font-outfit font-black text-white text-xl mb-6 flex items-center gap-3"><Bell className="text-blue-500" /> Dispatch Test Matrix</h2>

                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] font-bold uppercase tracking-widest text-[#C9A84C] mb-2 block">Notification Channel</label>
                                <select value={testPayload.channel} onChange={(e) => setTestPayload({ ...testPayload, channel: e.target.value })} className="w-full bg-white/5 border border-white/10 rounded-lg p-3 text-white text-sm focus:border-blue-500 outline-none hover:bg-white/10 transition-colors">
                                    <option value="email">Email Routing (Resend API)</option>
                                    <option value="whatsapp">WhatsApp Cloud (360dialog)</option>
                                    <option value="sms">Carrier SMS (Clickatell)</option>
                                </select>
                            </div>
                            <div>
                                <label className="text-[10px] font-bold uppercase tracking-widest text-[#C9A84C] mb-2 block">Destination (Email or Mobile)</label>
                                <input type="text" value={testPayload.destination} onChange={(e) => setTestPayload({ ...testPayload, destination: e.target.value })} placeholder="+27 82 555 1234 or email@..." className="w-full bg-black/50 border border-white/10 rounded-lg p-3 text-white font-mono text-sm focus:border-blue-500 outline-none transition-colors" />
                            </div>
                        </div>

                        <div className="flex justify-end gap-3 mt-8">
                            <button onClick={() => { setTestModal(false); setTestStatus(''); }} className="px-4 py-2 border border-white/10 rounded-lg text-white text-xs font-bold hover:bg-white/5 transition-colors uppercase tracking-wider">Cancel</button>
                            <button onClick={sendTestNotification} disabled={!testPayload.destination} className="px-5 py-2 bg-blue-500 text-white rounded-lg text-xs font-black uppercase tracking-wider hover:bg-blue-600 focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all disabled:opacity-50 disabled:cursor-not-allowed flex flex-row items-center gap-2">
                                {testStatus || 'Dispatch Simulation'} <Send size={14} />
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import Confetti from 'react-confetti';
import { MessageCircle, Car, Code, Users, CheckCircle, ChevronRight, Download, Upload, ExternalLink } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const steps = [
    { id: 1, title: 'Connect WhatsApp', icon: MessageCircle },
    { id: 2, title: 'Add Inventory', icon: Car },
    { id: 3, title: 'Embed Widget', icon: Code },
    { id: 4, title: 'Add Team', icon: Users },
    { id: 5, title: 'Go Live', icon: CheckCircle },
];

const Onboarding = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [currentStep, setCurrentStep] = useState(1);
    const [showConfetti, setShowConfetti] = useState(false);

    // Form states
    const [waKey, setWaKey] = useState('');
    const [waNumber, setWaNumber] = useState('');

    const handleNext = () => {
        if (currentStep < 5) {
            setCurrentStep(s => s + 1);
        }
    };

    const handleFinish = () => {
        setShowConfetti(true);
        setTimeout(() => {
            navigate('/dashboard');
        }, 4000); // 4 seconds of confetti before redirect
    };

    const currentStepData = steps.find(s => s.id === currentStep);

    return (
        <div className="min-h-screen flex items-center justify-center p-4 bg-[#080C17]"
            style={{ backgroundImage: 'radial-gradient(circle at 50% 0%, rgba(201,168,76,0.05) 0%, transparent 70%)' }}>

            {showConfetti && <Confetti width={window.innerWidth} height={window.innerHeight} colors={['#C9A84C', '#FFFFFF', '#0A0F1E']} />}

            <div className="w-full max-w-4xl bg-[#0B1120] rounded-3xl shadow-2xl border border-white/5 overflow-hidden flex flex-col md:flex-row min-h-[600px]">

                {/* Left Sidebar (Progress) */}
                <div className="w-full md:w-1/3 bg-[#111A30] p-8 border-r border-white/5 flex flex-col">
                    <div className="mb-12">
                        <h2 className="font-outfit font-black text-2xl text-white">Welcome,<br /><span className="text-[#C9A84C]">{user?.first_name || 'Dealer'}</span></h2>
                        <p className="text-white/40 text-sm mt-2">Let's set up your KenganAuto OS in just a few steps.</p>
                    </div>

                    <div className="flex-1 space-y-6">
                        {steps.map(step => (
                            <div key={step.id} className={`flex items-center gap-4 transition-opacity ${step.id > currentStep ? 'opacity-30' : 'opacity-100'}`}>
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-colors
                  ${step.id === currentStep ? 'border-[#C9A84C] text-[#C9A84C] bg-[#C9A84C]/10' :
                                        step.id < currentStep ? 'border-emerald-400 text-emerald-400 bg-emerald-400/10' : 'border-white/10 text-white/50 bg-white/5'}`}>
                                    {step.id < currentStep ? <CheckCircle size={18} /> : <step.icon size={18} />}
                                </div>
                                <div>
                                    <p className={`text-sm font-bold uppercase tracking-wider ${step.id === currentStep ? 'text-white' : 'text-white/50'}`}>
                                        Step {step.id}
                                    </p>
                                    <p className={`text-xs ${step.id === currentStep ? 'text-[#C9A84C]' : 'text-white/30'}`}>
                                        {step.title}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Right Content Area */}
                <div className="w-full md:w-2/3 p-8 md:p-12 relative flex flex-col overflow-y-auto hidden-scrollbar">
                    <AnimatePresence mode="wait">
                        <motion.div
                            key={currentStep}
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                            transition={{ duration: 0.3 }}
                            className="flex-1 flex flex-col justify-center"
                        >

                            {/* STEP 1: Connect WhatsApp */}
                            {currentStep === 1 && (
                                <div className="space-y-6">
                                    <h3 className="font-outfit font-black text-3xl text-white">Connect WhatsApp</h3>
                                    <p className="text-white/50">Link your 360dialog account to capture leads automatically.</p>

                                    <div className="space-y-4 pt-4">
                                        <div>
                                            <label className="block text-xs font-bold text-white/50 uppercase tracking-widest mb-2">360dialog API Key</label>
                                            <input type="password" placeholder="D3BXXXXXXXXXXXXXXXX" value={waKey} onChange={e => setWaKey(e.target.value)}
                                                className="w-full bg-[#080C17] border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#C9A84C] transition-colors" />
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-white/50 uppercase tracking-widest mb-2">WhatsApp Number</label>
                                            <input type="text" placeholder="+27 82 000 0000" value={waNumber} onChange={e => setWaNumber(e.target.value)}
                                                className="w-full bg-[#080C17] border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#C9A84C] transition-colors" />
                                        </div>
                                        <button className="w-full py-3 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 text-white font-bold transition-colors">
                                            Test Connection
                                        </button>
                                        <p className="text-center text-xs text-[#C9A84C] cursor-pointer hover:underline flex items-center justify-center gap-1">
                                            <ExternalLink size={12} /> Watch Video Tutorial
                                        </p>
                                    </div>
                                </div>
                            )}

                            {/* STEP 2: Add Inventory */}
                            {currentStep === 2 && (
                                <div className="space-y-6">
                                    <h3 className="font-outfit font-black text-3xl text-white">Add Your Inventory</h3>
                                    <p className="text-white/50">Upload your vehicles so the AI can start quoting customers.</p>

                                    <div className="grid grid-cols-2 gap-4 pt-4">
                                        <div className="bg-[#111A30] border border-white/5 rounded-2xl p-6 flex flex-col items-center justify-center gap-3 text-center cursor-pointer hover:bg-white/5 transition-colors group">
                                            <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center text-[#C9A84C] group-hover:bg-[#C9A84C] group-hover:text-[#0A0F1E] transition-all">
                                                <Upload size={24} />
                                            </div>
                                            <h4 className="font-bold text-white">Bulk CSV Upload</h4>
                                            <p className="text-xs text-white/40">Upload a spreadsheet</p>
                                        </div>
                                        <div className="bg-[#111A30] border border-white/5 rounded-2xl p-6 flex flex-col items-center justify-center gap-3 text-center cursor-pointer hover:bg-white/5 transition-colors group">
                                            <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center text-white group-hover:bg-white group-hover:text-[#0A0F1E] transition-all">
                                                <Car size={24} />
                                            </div>
                                            <h4 className="font-bold text-white">Add Manually</h4>
                                            <p className="text-xs text-white/40">Enter one by one</p>
                                        </div>
                                    </div>
                                    <button className="w-full py-3 mt-4 rounded-xl border border-white/5 flex items-center justify-center gap-2 text-white/50 hover:text-white hover:bg-white/5 transition-colors">
                                        <Download size={16} /> Download CSV Template
                                    </button>
                                </div>
                            )}

                            {/* STEP 3: Embed Widget */}
                            {currentStep === 3 && (
                                <div className="space-y-6">
                                    <h3 className="font-outfit font-black text-3xl text-white">Embed Web Widget</h3>
                                    <p className="text-white/50">Paste this line of code before the closing <code className="text-[#C9A84C]">&lt;/body&gt;</code> tag of your website (WordPress, Wix, etc).</p>

                                    <div className="bg-[#080C17] border border-white/10 rounded-xl p-4 relative font-mono text-sm text-white/70 overflow-x-auto">
                                        &lt;script src="https://kenganauto.co.za/api/widget.js?tenant={user?.tenant_id || 'demo'}" defer&gt;&lt;/script&gt;
                                        <button className="absolute top-2 right-2 bg-white/10 hover:bg-white/20 px-3 py-1 rounded text-xs font-bold text-white transition-colors"
                                            onClick={() => navigator.clipboard.writeText(`<script src="https://kenganauto.co.za/api/widget.js?tenant=${user?.tenant_id || 'demo'}" defer></script>`)}>
                                            Copy
                                        </button>
                                    </div>

                                    <div className="space-y-2">
                                        <p className="text-xs font-bold uppercase tracking-widest text-white/30">Integration Guides</p>
                                        <div className="flex gap-2">
                                            <span className="px-3 py-1 rounded bg-white/5 text-xs text-white/60 hover:text-white cursor-pointer transition-colors">WordPress</span>
                                            <span className="px-3 py-1 rounded bg-white/5 text-xs text-white/60 hover:text-white cursor-pointer transition-colors">Wix</span>
                                            <span className="px-3 py-1 rounded bg-white/5 text-xs text-white/60 hover:text-white cursor-pointer transition-colors">Squarespace</span>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {/* STEP 4: Add Team */}
                            {currentStep === 4 && (
                                <div className="space-y-6">
                                    <h3 className="font-outfit font-black text-3xl text-white">Add Your Team</h3>
                                    <p className="text-white/50">Invite colleagues to help manage leads and vehicle stock.</p>

                                    <div className="space-y-3">
                                        <div className="flex gap-2">
                                            <input type="email" placeholder="Email Address"
                                                className="flex-1 bg-[#080C17] border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#C9A84C]" />
                                            <select className="bg-[#080C17] border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#C9A84C]">
                                                <option value="salesperson">Salesperson</option>
                                                <option value="finance_manager">Finance Manager</option>
                                                <option value="service_advisor">Service Advisor</option>
                                            </select>
                                        </div>
                                        <button className="w-full py-3 rounded-xl bg-white/5 hover:bg-white/10 text-white font-bold transition-colors">
                                            + Invite Member
                                        </button>
                                    </div>
                                </div>
                            )}

                            {/* STEP 5: Go Live */}
                            {currentStep === 5 && (
                                <div className="space-y-6 text-center">
                                    <div className="w-24 h-24 mx-auto bg-emerald-400/10 text-emerald-400 rounded-full flex items-center justify-center">
                                        <CheckCircle size={48} />
                                    </div>
                                    <h3 className="font-outfit font-black text-4xl text-white">You're Ready!</h3>
                                    <p className="text-white/50">Your dealership is now powered by KenganAuto OS.</p>

                                    <div className="bg-[#111A30] border border-white/5 rounded-2xl p-6 text-left space-y-3 mt-6">
                                        <p className="text-xs font-bold tracking-widest uppercase text-white/30 mb-4">Launch Checklist</p>
                                        <div className="flex items-center gap-3 text-white/70">
                                            <CheckCircle size={16} className="text-emerald-400" /> WhatsApp API Active
                                        </div>
                                        <div className="flex items-center gap-3 text-white/70">
                                            <CheckCircle size={16} className="text-emerald-400" /> Inventory Populated
                                        </div>
                                        <div className="flex items-center gap-3 text-white/70">
                                            <CheckCircle size={16} className="text-emerald-400" /> Widget Copied
                                        </div>
                                    </div>
                                </div>
                            )}

                        </motion.div>
                    </AnimatePresence>

                    {/* Footer Controls */}
                    <div className="mt-auto pt-8 flex items-center justify-between border-t border-white/5">
                        {currentStep > 1 && currentStep < 5 ? (
                            <button onClick={() => setCurrentStep(s => s - 1)} className="px-6 py-2 rounded-xl text-white/50 hover:text-white transition-colors">
                                Back
                            </button>
                        ) : <div />}

                        {currentStep < 5 ? (
                            <div className="flex items-center gap-4">
                                <button onClick={handleNext} className="text-sm font-bold text-white/40 hover:text-white transition-colors">Skip for now</button>
                                <button onClick={handleNext} className="flex items-center gap-2 px-6 py-3 rounded-xl bg-[#C9A84C] text-[#0A0F1E] font-bold shadow-lg hover:opacity-90 transition-opacity">
                                    Next Step <ChevronRight size={18} />
                                </button>
                            </div>
                        ) : (
                            <button onClick={handleFinish} className="w-full flex items-center justify-center gap-2 px-6 py-4 rounded-xl bg-emerald-400 text-[#0A0F1E] font-black shadow-lg hover:opacity-90 transition-opacity whitespace-nowrap text-lg uppercase tracking-wider">
                                Launch Dealership <RocketIcon />
                            </button>
                        )}
                    </div>

                </div>
            </div>
        </div>
    );
};

const RocketIcon = () => (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2c.71-.84.7-2.13-.09-2.91a2.18 2.18 0 0 0-2.91-.09z" />
        <path d="m12 15-3-3a22 22 0 0 1 2-3.95A12.88 12.88 0 0 1 22 2c0 2.72-.78 7.5-6 11a22.35 22.35 0 0 1-4 2z" />
        <path d="M9 12H4s.55-3.03 2-4c1.62-1.08 5 0 5 0" />
        <path d="M12 15v5s3.03-.55 4-2c1.08-1.62 0-5 0-5" />
    </svg>
)

export default Onboarding;

