import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import {
    Settings, Package, CheckCircle, Search, Clock, FileText, Send,
    Download, Upload, Tag, TrendingUp, AlertCircle, Phone
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000';

const STATUS_STYLE = {
    'enquiry': { bg: 'bg-white/5', border: 'border-white/10', text: 'text-white/60' },
    'quoted': { bg: 'bg-orange-500/10', border: 'border-orange-500/20', text: 'text-orange-400' },
    'ordered': { bg: 'bg-blue-500/10', border: 'border-blue-500/20', text: 'text-blue-400' },
    'ready': { bg: 'bg-green-500/10', border: 'border-green-500/20', text: 'text-green-400' },
    'collected': { bg: 'bg-white/5', border: 'border-white/10', text: 'text-white/30' },
};

export default function Parts() {
    const { user } = useAuth();
    const [view, setView] = useState('enquiries'); // 'enquiries', 'catalog', 'analytics'
    const [enquiries, setEnquiries] = useState([]);
    const [catalog, setCatalog] = useState([]);
    const [analytics, setAnalytics] = useState(null);
    const [loading, setLoading] = useState(true);

    const [selectedEnquiry, setSelectedEnquiry] = useState(null);
    const [isBulkOpen, setIsBulkOpen] = useState(false);
    const fileRef = useRef(null);

    useEffect(() => {
        if (view === 'enquiries') loadEnquiries();
        else if (view === 'catalog') loadCatalog();
        else if (view === 'analytics') loadAnalytics();
    }, [view]);

    const loadEnquiries = async () => {
        setLoading(true);
        try {
            const res = await axios.get(`${API_URL}/api/parts/enquiries`);
            setEnquiries(res.data);
        } catch (e) { console.error(e); }
        setLoading(false);
    };

    const loadCatalog = async () => {
        setLoading(true);
        try {
            const res = await axios.get(`${API_URL}/api/parts/catalog`);
            setCatalog(res.data);
        } catch (e) { }
        setLoading(false);
    };

    const loadAnalytics = async () => {
        try {
            const res = await axios.get(`${API_URL}/api/parts/analytics`);
            setAnalytics(res.data);
        } catch (e) { }
    };

    const updateStatus = async (id, status, extraData = {}) => {
        try {
            const res = await axios.patch(`${API_URL}/api/parts/enquiries/${id}`, { status, ...extraData });
            setEnquiries(prev => prev.map(e => e.id === id ? res.data.enquiry : e));
            setSelectedEnquiry(null);
        } catch (e) { alert('Update failed'); }
    };

    const handleFileUpload = (e) => {
        const file = e.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (evt) => {
            const text = evt.target.result;
            const rows = text.split('\\n');
            const parsed = [];
            for (let i = 1; i < rows.length; i++) {
                if (!rows[i].trim()) continue;
                const cols = rows[i].split(',').map(c => c.trim().replace(/"/g, ''));
                parsed.push({
                    part_number: cols[0],
                    description: cols[1],
                    fitment: cols[2],
                    price: Number(cols[3]),
                    stock: Number(cols[4])
                });
            }
            try {
                await axios.post(`${API_URL}/api/parts/catalog/bulk`, { parts: parsed });
                setIsBulkOpen(false);
                loadCatalog();
            } catch (e) { alert('Upload failed. Check format.'); }
        };
        reader.readAsText(file);
    };

    const renderQuotePanel = () => {
        if (!selectedEnquiry) return null;
        return (
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm z-50 flex justify-end">
                <div className="w-[450px] h-full shadow-2xl overflow-y-auto p-6 flex flex-col anim-slide-left"
                    style={{ background: '#0D1526', borderLeft: '1px solid rgba(201,168,76,0.15)' }}>
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="font-outfit font-black text-xl">Manage Enquiry</h2>
                        <button onClick={() => setSelectedEnquiry(null)} className="p-2 text-white/50 hover:text-white rounded-full"><X size={20} /></button>
                    </div>

                    <div className="bg-white/5 border border-white/10 rounded-xl p-4 mb-6">
                        <p className="text-[10px] uppercase font-bold text-white/40 mb-3 tracking-widest">Request Details</p>
                        <p className="font-bold text-lg text-white mb-1">{selectedEnquiry.vehicle_make} {selectedEnquiry.vehicle_model}</p>
                        <div className="flex justify-between items-end border-b border-white/10 pb-3 mb-3">
                            <p className="text-sm font-black text-[#C9A84C]">{selectedEnquiry.part_name}</p>
                            <p className="text-xs text-white/40 font-mono">PN: {selectedEnquiry.part_number || 'Unknown'}</p>
                        </div>
                        <p className="flex justify-between text-xs"><span className="text-white/50">Customer</span> <span className="font-bold">{selectedEnquiry.customer_name}</span></p>
                        {selectedEnquiry.customer_phone && <p className="flex justify-between text-xs mt-1"><span className="text-white/50">Phone</span> <span>{selectedEnquiry.customer_phone}</span></p>}
                    </div>

                    <div className="flex-1 space-y-4">
                        <p className="text-[10px] uppercase font-bold text-white/40 tracking-widest mb-2">Update Stage</p>
                        <div className="grid grid-cols-2 gap-3">
                            <button onClick={() => updateStatus(selectedEnquiry.id, 'quoted')} className="p-3 border border-white/10 rounded-xl text-xs font-bold hover:bg-white/5 text-orange-400">Mark Quoted</button>
                            <button onClick={() => updateStatus(selectedEnquiry.id, 'ordered')} className="p-3 border border-white/10 rounded-xl text-xs font-bold hover:bg-white/5 text-blue-400">Mark Ordered</button>
                            <button onClick={() => updateStatus(selectedEnquiry.id, 'ready')} className="p-3 border border-white/10 rounded-xl text-xs font-bold hover:bg-white/5 text-green-400 col-span-2">Mark Ready for Collection</button>
                            <button onClick={() => updateStatus(selectedEnquiry.id, 'collected')} className="p-3 border border-white/10 rounded-xl text-xs font-bold hover:bg-white/5 text-white/40 col-span-2">Mark Collected</button>
                        </div>
                        <p className="text-[9px] text-white/30 text-center mt-2">* 'Ready for Collection' auto-notifies the customer via WhatsApp.</p>
                    </div>

                    <div className="mt-8 border-t border-white/10 pt-4">
                        <label className="text-[10px] uppercase font-black text-white/40 block mb-2">Price Estimate (ZAR)</label>
                        <input type="number" defaultValue={selectedEnquiry.price_quoted || ''} placeholder="0.00"
                            onBlur={e => updateStatus(selectedEnquiry.id, selectedEnquiry.status, { price_quoted: Number(e.target.value) })}
                            className="w-full text-xl font-black bg-transparent border-b border-white/20 outline-none pb-2 focus:border-[#C9A84C]" />
                    </div>
                </div>
            </div>
        );
    };

    return (
        <div className="flex flex-col h-screen bg-[#0A0F1E] text-white">
            <header className="px-8 py-5 flex items-center justify-between sticky top-0 z-10"
                style={{ background: 'rgba(10,15,30,0.85)', backdropFilter: 'blur(20px)', borderBottom: '1px solid rgba(201,168,76,0.08)' }}>
                <div className="flex items-center gap-4">
                    <div className="p-2.5 rounded-xl bg-purple-500/10 border border-purple-500/20 text-purple-400">
                        <Settings size={20} />
                    </div>
                    <div>
                        <p className="text-[9px] font-black uppercase tracking-[0.3em] mb-0.5" style={{ color: 'rgba(201,168,76,0.4)' }}>Module</p>
                        <h1 className="font-outfit font-black text-xl text-white">Parts Department</h1>
                    </div>
                </div>

                <div className="flex gap-2">
                    <button onClick={() => setView('enquiries')} className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${view === 'enquiries' ? 'bg-[#C9A84C] text-[#0A0F1E]' : 'hover:bg-white/5 border border-white/10'}`}>Enquiries Pipeline</button>
                    <button onClick={() => setView('catalog')} className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${view === 'catalog' ? 'bg-[#C9A84C] text-[#0A0F1E]' : 'hover:bg-white/5 border border-white/10'}`}>Parts Database</button>
                    {(user?.role === 'admin' || user?.role === 'manager') && (
                        <button onClick={() => setView('analytics')} className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${view === 'analytics' ? 'bg-[#C9A84C] text-[#0A0F1E]' : 'hover:bg-white/5 border border-white/10'}`}>Revenue Tracker</button>
                    )}
                </div>
            </header>

            <div className="flex-1 overflow-auto p-8 relative">
                {view === 'enquiries' && (
                    <div className="grid grid-cols-4 gap-6 h-full">
                        {['enquiry', 'quoted', 'ordered', 'ready'].map(status => (
                            <div key={status} className="bg-white/5 border border-white/5 rounded-2xl p-4 overflow-y-auto">
                                <h3 className="text-[10px] uppercase font-black tracking-widest text-white/40 mb-4 sticky top-0 bg-[#0F162A] py-2">
                                    {status.replace(/_/g, ' ')}
                                </h3>
                                <div className="space-y-3">
                                    {enquiries.filter(e => e.status === status).map(e => (
                                        <div key={e.id} onClick={() => setSelectedEnquiry(e)}
                                            className={`bg-black/40 p-4 rounded-xl border border-white/5 cursor-pointer hover:scale-[1.02] transition-transform ${e.customer_name.startsWith('INTERNAL') ? 'border-orange-500/30 bg-orange-500/5' : ''}`}>
                                            {e.customer_name.startsWith('INTERNAL') && <span className="text-[8px] font-black uppercase bg-orange-500 text-white px-2 py-0.5 rounded mb-2 inline-block">WORKSHOP REQUEST</span>}
                                            <p className="text-sm font-black text-[#C9A84C]">{e.part_name}</p>
                                            <p className="text-[10px] text-white/60 mb-2">{e.vehicle_make} {e.vehicle_model}</p>
                                            <div className="flex justify-between items-center text-xs">
                                                <span className="font-bold">{e.customer_name.replace('INTERNAL: ', '')}</span>
                                                {e.price_quoted && <span className="font-mono text-white/40">R{e.price_quoted}</span>}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {view === 'catalog' && (
                    <div>
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-lg font-outfit font-black">Stock Catalogue</h2>
                            <button onClick={() => setIsBulkOpen(true)} className="px-4 py-2 text-[10px] font-bold uppercase tracking-widest bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded-xl flex items-center gap-2">
                                <Upload size={14} /> CSV Upload
                            </button>
                        </div>

                        {loading ? <p className="text-white/30 text-xs text-center mt-10">Loading catalog...</p> : (
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="text-[9px] uppercase tracking-widest text-white/40 border-b border-white/5">
                                        <th className="pb-3 font-black">Part Number</th>
                                        <th className="pb-3 font-black">Description & Fitment</th>
                                        <th className="pb-3 font-black text-right">Price (ZAR)</th>
                                        <th className="pb-3 font-black text-center">Stock</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {catalog.map((p, i) => (
                                        <tr key={i} className="border-b border-white/5 group hover:bg-white/5">
                                            <td className="py-4 font-mono text-xs text-[#C9A84C] font-bold">{p.part_number}</td>
                                            <td className="py-4">
                                                <p className="text-sm font-bold text-white">{p.description}</p>
                                                <p className="text-[10px] text-white/40">{p.fitment}</p>
                                            </td>
                                            <td className="py-4 text-right font-black">R{p.price.toLocaleString()}</td>
                                            <td className="py-4 text-center">
                                                <span className={`px-2 py-1 rounded-full text-[10px] font-bold ${p.stock > 0 ? 'bg-green-500/10 text-green-400 border border-green-500/20' : 'bg-red-500/10 text-red-500 border border-red-500/20'}`}>
                                                    {p.stock} units
                                                </span>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        )}
                    </div>
                )}

                {view === 'analytics' && analytics && (
                    <div className="max-w-4xl mx-auto space-y-8">
                        <div className="grid grid-cols-3 gap-6">
                            <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                                <p className="text-[10px] uppercase tracking-widest text-white/40 font-bold mb-2">Total Monthly Revenue (Collected)</p>
                                <p className="text-3xl font-black text-green-400">R {analytics.revenue_this_month.toLocaleString()}</p>
                            </div>
                            <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                                <p className="text-[10px] uppercase tracking-widest text-white/40 font-bold mb-2">Pending Orders Value</p>
                                <p className="text-3xl font-black text-orange-400">R {analytics.pending_orders_value.toLocaleString()}</p>
                            </div>
                            <div className="bg-white/5 p-6 rounded-2xl border border-white/10 relative overflow-hidden">
                                <p className="text-[10px] uppercase tracking-widest text-white/40 font-bold mb-2">Collection Rate</p>
                                <p className="text-3xl font-black text-white">{analytics.collection_rate}%</p>
                                <div className="absolute top-0 right-0 p-4 opacity-10"><CheckCircle size={80} /></div>
                            </div>
                        </div>

                        <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                            <h3 className="text-xs font-bold uppercase tracking-widest text-white/50 mb-6">Top-Selling Parts</h3>
                            <div className="space-y-4">
                                {analytics.top_selling_parts.map((p, i) => (
                                    <div key={i} className="flex justify-between items-center bg-black/30 p-4 rounded-xl border border-white/5">
                                        <p className="font-bold">{p.name}</p>
                                        <span className="font-mono text-[#C9A84C] font-black">{p.count} sold</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {renderQuotePanel()}

            {/* ── Modal: Bulk Import ── */}
            {isBulkOpen && (
                <div className="absolute inset-0 bg-black/80 backdrop-blur-md z-50 flex items-center justify-center anim-fade-up">
                    <div className="bg-[#0D1526] border border-white/10 p-8 rounded-2xl shadow-2xl w-[500px] relative text-center">
                        <button onClick={() => setIsBulkOpen(false)} className="absolute top-4 right-4 p-2 text-white/50 hover:bg-white/10 rounded-full"><X size={20} /></button>
                        <Upload size={30} className="mx-auto text-blue-400 mb-4" />
                        <h2 className="font-outfit font-black text-xl mb-2">Upload Parts CSV</h2>
                        <p className="text-xs text-white/50 mb-6">Upload an excel or comma separated file with columns:<br /> <code>Part Number, Description, Fitment, Price, Stock</code></p>

                        <div className="border border-dashed border-white/20 rounded-xl p-8 hover:bg-white/5 transition-colors cursor-pointer"
                            onClick={() => fileRef.current?.click()}>
                            <input type="file" accept=".csv" ref={fileRef} onChange={handleFileUpload} className="hidden" />
                            <FileText size={24} className="mx-auto text-white/30 mb-3" />
                            <p className="text-sm font-bold text-white">Click to select CSV</p>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useEffect, useMemo, useState } from 'react';
import {
    Activity,
    CalendarClock,
    ChevronDown,
    ChevronUp,
    Crown,
    Gift,
    Heart,
    Lock,
    Mail,
    MessageCircle,
    Play,
    RefreshCw,
    Send,
    Smartphone,
    ToggleLeft,
    ToggleRight,
    Users,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { PageShell, Surface } from '../components/PageShell';
import CollapsibleSection from '../components/CollapsibleSection';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000';

const CHANNEL_OPTIONS = [
    { value: 'whatsapp', label: 'WhatsApp', icon: MessageCircle },
    { value: 'email', label: 'Email', icon: Mail },
    { value: 'sms', label: 'SMS', icon: Smartphone },
];

const AUDIENCE_OPTIONS = [
    { value: 'dormant_leads', label: 'Old leads' },
    { value: 'service_due', label: 'Service due' },
    { value: 'birthdays', label: 'Birthdays' },
    { value: 'all_customers', label: 'All customers' },
];

const SCHEDULE_OPTIONS = [
    { value: 'once', label: 'One-off' },
    { value: 'daily', label: 'Daily' },
    { value: 'weekly', label: 'Weekly' },
    { value: 'monthly', label: 'Monthly' },
];

const DEFAULT_FORM = {
    name: 'Weekend reactivation blast',
    channel: 'whatsapp',
    audience_type: 'dormant_leads',
    schedule_type: 'once',
    template_subject: 'You are invited back to {{dealershipName}}',
    template_body: 'Hi {{firstName}}, we have fresh stock and flexible options available for {{vehicleInterest}} buyers this week. If you want, we can book you in for a quick test drive at {{dealershipName}}.',
};

function getToken() {
    return localStorage.getItem('ka_token') || localStorage.getItem('token');
}

async function apiFetch(path, options = {}) {
    const token = getToken();
    const response = await fetch(`${API_URL}${path}`, {
        ...options,
        headers: {
            'Content-Type': 'application/json',
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
            ...(options.headers || {}),
        },
    });

    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
        throw new Error(data.error || 'Request failed.');
    }

    return data;
}

function SectionHeader({ title, subtitle, action }) {
    return (
        <div className="mb-5 flex flex-wrap items-start justify-between gap-4">
            <div className="max-w-3xl">
                <h2 className="font-outfit text-2xl font-black text-white">{title}</h2>
                {subtitle ? <p className="mt-2 text-sm leading-7 text-white/56">{subtitle}</p> : null}
            </div>
            {action}
        </div>
    );
}

function StatCard({ icon: Icon, label, value, hint }) {
    return (
        <Surface className="rounded-2xl p-5">
            <div className="mb-3 flex items-center justify-between">
                <span className="text-sm font-semibold text-white/68">{label}</span>
                <div className="rounded-xl bg-white/5 p-2 text-[#C9A84C]">
                    <Icon size={16} />
                </div>
            </div>
            <p className="font-outfit text-4xl font-black text-white">{value}</p>
            <p className="mt-2 text-sm leading-6 text-white/44">{hint}</p>
        </Surface>
    );
}

function Pill({ children }) {
    return (
        <span className="rounded-full bg-white/6 px-3 py-1.5 text-xs font-semibold text-white/68">
            {children}
        </span>
    );
}

function AudiencePreview({ preview, previewLoading, audienceType }) {
    return (
        <Surface className="rounded-2xl p-5">
            <SectionHeader
                title="Audience preview"
                subtitle="Check the contact count before you send."
                action={previewLoading ? <RefreshCw size={16} className="animate-spin text-[#C9A84C]" /> : <Users size={16} className="text-[#C9A84C]" />}
            />

            <div className="rounded-2xl bg-[#0D1526] p-4">
                <p className="text-sm font-semibold text-white/70">{AUDIENCE_OPTIONS.find((item) => item.value === audienceType)?.label || 'Audience'}</p>
                <p className="mt-2 font-outfit text-4xl font-black text-white">{preview?.count || 0}</p>
            </div>

            <div className="mt-4 space-y-3">
                {(preview?.sample || []).map((person) => (
                    <div key={`${person.entity_type}-${person.entity_id}`} className="rounded-2xl border border-white/8 bg-[#0D1526] p-4">
                        <p className="text-sm font-semibold text-white">{person.full_name}</p>
                        <p className="mt-1 text-sm text-white/48">{person.email || person.whatsapp_number || person.phone || 'No contact method'}</p>
                    </div>
                ))}

                {!previewLoading && (!preview?.sample || preview.sample.length === 0) ? (
                    <div className="rounded-2xl border border-dashed border-white/10 bg-[#0D1526] p-4 text-sm leading-7 text-white/44">
                        No matching contacts yet. Add birthdays to customer records and keep service history current to improve coverage.
                    </div>
                ) : null}
            </div>
        </Surface>
    );
}

function CampaignCard({ campaign, onToggle, onRun, runningCampaignId }) {
    const channel = CHANNEL_OPTIONS.find((item) => item.value === campaign.channel);
    const ChannelIcon = channel?.icon || Send;

    return (
        <div className="rounded-2xl border border-white/10 bg-[#0D1526] p-5">
            <div className="flex flex-wrap items-start justify-between gap-4">
                <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                        <h3 className="font-outfit text-xl font-black text-white">{campaign.name}</h3>
                        <Pill>
                            <span className="inline-flex items-center gap-1.5">
                                <ChannelIcon size={12} className="text-[#C9A84C]" />
                                {channel?.label || campaign.channel}
                            </span>
                        </Pill>
                        <Pill>{AUDIENCE_OPTIONS.find((item) => item.value === campaign.audience_type)?.label || campaign.audience_type}</Pill>
                        <Pill>{campaign.schedule_type}</Pill>
                    </div>
                    <p className="mt-3 text-sm leading-7 text-white/54">{campaign.template_body}</p>
                    {campaign.last_run_summary?.executed_at ? (
                        <div className="mt-4 flex flex-wrap gap-3 text-sm text-white/45">
                            <span>Last run: {new Date(campaign.last_run_summary.executed_at).toLocaleString()}</span>
                            <span>Audience: {campaign.last_run_summary.audience_count || 0}</span>
                            <span className="text-green-300">Delivered: {campaign.last_run_summary.delivered_count || 0}</span>
                        </div>
                    ) : null}
                </div>

                <div className="flex items-center gap-3">
                    <button
                        onClick={() => onToggle(campaign)}
                        className={campaign.active ? 'text-green-400' : 'text-white/32'}
                        title={campaign.active ? 'Pause campaign' : 'Resume campaign'}
                    >
                        {campaign.active ? <ToggleRight size={34} /> : <ToggleLeft size={34} />}
                    </button>
                    <button
                        onClick={() => onRun(campaign.id)}
                        disabled={runningCampaignId === campaign.id}
                        className="inline-flex items-center gap-2 rounded-xl bg-[#C9A84C] px-4 py-2.5 text-sm font-semibold text-[#0A0F1E] transition hover:opacity-90 disabled:opacity-60"
                    >
                        <Play size={14} />
                        {runningCampaignId === campaign.id ? 'Running...' : 'Run now'}
                    </button>
                </div>
            </div>
        </div>
    );
}

function EmptyCard({ text }) {
    return (
        <div className="rounded-2xl border border-dashed border-white/10 bg-[#0D1526] p-5 text-sm leading-7 text-white/46">
            {text}
        </div>
    );
}

function TabBar({ view, setView }) {
    const tabs = [
        { id: 'reactivation', label: 'Database reactivation' },
        { id: 'sequences', label: 'Sequences' },
        { id: 'loyalty', label: 'Loyalty & NPS' },
    ];

    return (
        <div className="flex flex-wrap gap-2">
            {tabs.map((tab) => (
                <button
                    key={tab.id}
                    onClick={() => setView(tab.id)}
                    className={`rounded-2xl px-4 py-2.5 text-sm font-semibold transition ${view === tab.id ? 'bg-[#C9A84C] text-[#0A0F1E]' : 'border border-white/10 bg-[#121A2B] text-white/62 hover:text-white'}`}
                >
                    {tab.label}
                </button>
            ))}
        </div>
    );
}

export default function Retention() {
    const navigate = useNavigate();
    const [view, setView] = useState('reactivation');
    const [sequences, setSequences] = useState([]);
    const [loyaltyData, setLoyaltyData] = useState(null);
    const [expandedSeq, setExpandedSeq] = useState(null);
    const [reactivation, setReactivation] = useState(null);
    const [loading, setLoading] = useState(true);
    const [submitting, setSubmitting] = useState(false);
    const [processingDue, setProcessingDue] = useState(false);
    const [runningCampaignId, setRunningCampaignId] = useState(null);
    const [previewLoading, setPreviewLoading] = useState(false);
    const [preview, setPreview] = useState(null);
    const [form, setForm] = useState(DEFAULT_FORM);

    const automaticCampaigns = useMemo(
        () => (reactivation?.campaigns || []).filter((campaign) => campaign.is_automatic),
        [reactivation]
    );

    const manualCampaigns = useMemo(
        () => (reactivation?.campaigns || []).filter((campaign) => !campaign.is_automatic),
        [reactivation]
    );

    useEffect(() => {
        if (view === 'reactivation') {
            loadReactivation();
            return;
        }
        if (view === 'sequences') {
            loadSequences();
            return;
        }
        loadLoyalty();
    }, [view]);

    useEffect(() => {
        if (view !== 'reactivation' || reactivation?.locked) return;
        loadPreview(form.audience_type);
    }, [view, reactivation?.locked, form.audience_type]);

    const loadReactivation = async () => {
        setLoading(true);
        try {
            const data = await apiFetch('/api/retention/reactivation');
            setReactivation(data);
        } catch (error) {
            console.error('Error fetching database reactivation', error);
        } finally {
            setLoading(false);
        }
    };

    const loadSequences = async () => {
        setLoading(true);
        try {
            const data = await apiFetch('/api/retention/sequences');
            setSequences(data);
        } catch (error) {
            console.error('Error fetching sequences', error);
        } finally {
            setLoading(false);
        }
    };

    const loadLoyalty = async () => {
        setLoading(true);
        try {
            const data = await apiFetch('/api/retention/loyalty-nps');
            setLoyaltyData(data);
        } catch (error) {
            console.error('Error fetching loyalty data', error);
        } finally {
            setLoading(false);
        }
    };

    const loadPreview = async (audienceType) => {
        setPreviewLoading(true);
        try {
            const data = await apiFetch(`/api/retention/reactivation/audience-preview?audience_type=${audienceType}`);
            setPreview(data);
        } catch (error) {
            console.error('Error previewing audience', error);
        } finally {
            setPreviewLoading(false);
        }
    };

    const toggleSequence = async (id, activeStatus) => {
        try {
            const data = await apiFetch(`/api/retention/sequences/${id}/toggle`, {
                method: 'PATCH',
                body: JSON.stringify({ active: !activeStatus }),
            });
            setSequences((current) => current.map((sequence) => (sequence.id === id ? data : sequence)));
        } catch (error) {
            alert(error.message || 'Failed to toggle sequence.');
        }
    };

    const toggleCampaign = async (campaign) => {
        try {
            await apiFetch(`/api/retention/reactivation/campaigns/${campaign.id}`, {
                method: 'PATCH',
                body: JSON.stringify({ active: !campaign.active }),
            });
            await loadReactivation();
        } catch (error) {
            alert(error.message || 'Failed to update campaign.');
        }
    };

    const runCampaign = async (campaignId) => {
        setRunningCampaignId(campaignId);
        try {
            await apiFetch(`/api/retention/reactivation/campaigns/${campaignId}/run`, { method: 'POST' });
            await loadReactivation();
        } catch (error) {
            alert(error.message || 'Failed to run campaign.');
        } finally {
            setRunningCampaignId(null);
        }
    };

    const processDueCampaigns = async () => {
        setProcessingDue(true);
        try {
            await apiFetch('/api/retention/reactivation/process-due', { method: 'POST' });
            await loadReactivation();
        } catch (error) {
            alert(error.message || 'Failed to process due automations.');
        } finally {
            setProcessingDue(false);
        }
    };

    const handleCreateCampaign = async (event) => {
        event.preventDefault();
        setSubmitting(true);
        try {
            await apiFetch('/api/retention/reactivation/campaigns', {
                method: 'POST',
                body: JSON.stringify({
                    ...form,
                    kind: 'manual',
                    active: true,
                }),
            });
            setForm(DEFAULT_FORM);
            await loadReactivation();
        } catch (error) {
            alert(error.message || 'Failed to create campaign.');
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <PageShell
            eyebrow="Retention"
            title="Database reactivation"
            description="This page is now structured around the actual workflow: check the audience, review the automatic campaigns, then create one manual campaign if you need it."
            actions={
                <div className="flex flex-wrap items-center gap-3">
                    {view === 'reactivation' && !reactivation?.locked ? (
                        <button
                            onClick={processDueCampaigns}
                            disabled={processingDue}
                            className="inline-flex items-center gap-2 rounded-2xl border border-[#C9A84C]/25 bg-[#C9A84C]/10 px-4 py-2.5 text-sm font-semibold text-[#F7D774] transition hover:bg-[#C9A84C]/15 disabled:opacity-60"
                        >
                            <RefreshCw size={15} className={processingDue ? 'animate-spin' : ''} />
                            {processingDue ? 'Processing...' : 'Process due'}
                        </button>
                    ) : null}
                    <TabBar view={view} setView={setView} />
                </div>
            }
            maxWidth="max-w-[1440px]"
        >
            {view === 'reactivation' ? (
                loading ? (
                    <Surface className="rounded-3xl p-10 text-center text-sm text-white/42">Loading database reactivation...</Surface>
                ) : reactivation?.locked ? (
                    <div className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
                        <Surface className="rounded-3xl">
                            <SectionHeader
                                title="Database reactivation is on Enterprise"
                                subtitle="Unlock automated service reminders, birthday outreach, old lead reactivation, and a campaign builder from one page."
                                action={
                                    <button
                                        onClick={() => navigate('/settings/billing')}
                                        className="rounded-xl bg-[#C9A84C] px-5 py-3 text-sm font-semibold text-[#0A0F1E] transition hover:opacity-90"
                                    >
                                        Upgrade plan
                                    </button>
                                }
                            />

                            <div className="grid gap-4 md:grid-cols-2">
                                {(reactivation.enterprise_features || []).map((feature) => (
                                    <div key={feature} className="rounded-2xl border border-white/10 bg-[#0D1526] p-4 text-sm leading-7 text-white/68">
                                        {feature}
                                    </div>
                                ))}
                            </div>
                        </Surface>

                        <Surface className="rounded-3xl">
                            <SectionHeader title="Current access" subtitle={reactivation.upgrade_message} />
                            <div className="rounded-2xl border border-white/10 bg-[#0D1526] p-5">
                                <div className="flex items-center gap-3">
                                    <div className="rounded-xl bg-red-500/10 p-2 text-red-400">
                                        <Lock size={16} />
                                    </div>
                                    <div>
                                        <p className="text-sm text-white/46">Plan</p>
                                        <p className="mt-1 font-outfit text-2xl font-black text-white">{reactivation.plan?.toUpperCase()}</p>
                                    </div>
                                </div>
                            </div>
                        </Surface>
                    </div>
                ) : (
                    <>
                        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
                            <StatCard icon={CalendarClock} label="Service due" value={reactivation?.audience_preview?.service_due || 0} hint="Customers entering the next service window." />
                            <StatCard icon={Gift} label="Birthdays" value={reactivation?.audience_preview?.birthdays || 0} hint="Customers with birthdays inside the reminder window." />
                            <StatCard icon={Activity} label="Old leads" value={reactivation?.audience_preview?.dormant_leads || 0} hint="Leads ready for a fresh follow-up." />
                            <StatCard icon={Crown} label="Plan" value={reactivation?.plan?.toUpperCase() || 'ENTERPRISE'} hint="Database reactivation is available." />
                        </div>

                        <div className="grid gap-6 xl:grid-cols-[minmax(0,1.45fr)_360px]">
                            <div className="space-y-6">
                                <Surface className="rounded-3xl">
                                    <SectionHeader
                                        title="Automatic campaigns"
                                        subtitle="These stay on in the background. Your team should only need to review them and run a manual test when needed."
                                    />
                                    <div className="space-y-4">
                                        {automaticCampaigns.length ? automaticCampaigns.map((campaign) => (
                                            <CampaignCard
                                                key={campaign.id}
                                                campaign={campaign}
                                                onToggle={toggleCampaign}
                                                onRun={runCampaign}
                                                runningCampaignId={runningCampaignId}
                                            />
                                        )) : <EmptyCard text="No automatic campaigns are available yet." />}
                                    </div>
                                </Surface>

                                <Surface className="rounded-3xl">
                                    <SectionHeader
                                        title="Manual campaign"
                                        subtitle="Use this only for one-off pushes. The advanced builder stays collapsed until the user chooses to open it."
                                    />

                                    <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_340px]">
                                        <div className="space-y-4">
                                            <div className="grid gap-4 md:grid-cols-2">
                                                <label className="space-y-2">
                                                    <span className="text-sm font-medium text-white/60">Campaign name</span>
                                                    <input
                                                        value={form.name}
                                                        onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))}
                                                        className="w-full rounded-2xl border border-white/10 bg-[#0D1526] px-4 py-3 text-sm text-white outline-none transition focus:border-[#C9A84C]/35"
                                                    />
                                                </label>

                                                <label className="space-y-2">
                                                    <span className="text-sm font-medium text-white/60">Audience</span>
                                                    <select
                                                        value={form.audience_type}
                                                        onChange={(event) => setForm((current) => ({ ...current, audience_type: event.target.value }))}
                                                        className="w-full rounded-2xl border border-white/10 bg-[#0D1526] px-4 py-3 text-sm text-white outline-none transition focus:border-[#C9A84C]/35"
                                                    >
                                                        {AUDIENCE_OPTIONS.map((option) => (
                                                            <option key={option.value} value={option.value}>{option.label}</option>
                                                        ))}
                                                    </select>
                                                </label>
                                            </div>

                                            <CollapsibleSection
                                                title="Message and delivery options"
                                                subtitle="Channel, schedule, subject, and message template."
                                                defaultOpen
                                            >
                                                <form onSubmit={handleCreateCampaign} className="space-y-4">
                                                    <div className="grid gap-4 md:grid-cols-2">
                                                        <label className="space-y-2">
                                                            <span className="text-sm font-medium text-white/60">Channel</span>
                                                            <select
                                                                value={form.channel}
                                                                onChange={(event) => setForm((current) => ({ ...current, channel: event.target.value }))}
                                                                className="w-full rounded-2xl border border-white/10 bg-[#0D1526] px-4 py-3 text-sm text-white outline-none transition focus:border-[#C9A84C]/35"
                                                            >
                                                                {CHANNEL_OPTIONS.map((option) => (
                                                                    <option key={option.value} value={option.value}>{option.label}</option>
                                                                ))}
                                                            </select>
                                                        </label>

                                                        <label className="space-y-2">
                                                            <span className="text-sm font-medium text-white/60">Schedule</span>
                                                            <select
                                                                value={form.schedule_type}
                                                                onChange={(event) => setForm((current) => ({ ...current, schedule_type: event.target.value }))}
                                                                className="w-full rounded-2xl border border-white/10 bg-[#0D1526] px-4 py-3 text-sm text-white outline-none transition focus:border-[#C9A84C]/35"
                                                            >
                                                                {SCHEDULE_OPTIONS.map((option) => (
                                                                    <option key={option.value} value={option.value}>{option.label}</option>
                                                                ))}
                                                            </select>
                                                        </label>
                                                    </div>

                                                    {form.channel === 'email' ? (
                                                        <label className="space-y-2">
                                                            <span className="text-sm font-medium text-white/60">Email subject</span>
                                                            <input
                                                                value={form.template_subject}
                                                                onChange={(event) => setForm((current) => ({ ...current, template_subject: event.target.value }))}
                                                                className="w-full rounded-2xl border border-white/10 bg-[#0D1526] px-4 py-3 text-sm text-white outline-none transition focus:border-[#C9A84C]/35"
                                                            />
                                                        </label>
                                                    ) : null}

                                                    <label className="space-y-2">
                                                        <span className="text-sm font-medium text-white/60">Message</span>
                                                        <textarea
                                                            rows={6}
                                                            value={form.template_body}
                                                            onChange={(event) => setForm((current) => ({ ...current, template_body: event.target.value }))}
                                                            className="w-full rounded-2xl border border-white/10 bg-[#0D1526] px-4 py-4 text-sm leading-7 text-white outline-none transition focus:border-[#C9A84C]/35"
                                                        />
                                                    </label>

                                                    <div className="rounded-2xl bg-[#0D1526] p-4">
                                                        <p className="text-sm leading-7 text-white/50">
                                                            Personalisation tokens: <span className="text-[#C9A84C]">{'{{firstName}}'}</span>, <span className="text-[#C9A84C]">{'{{vehicleInterest}}'}</span>, <span className="text-[#C9A84C]">{'{{dealershipName}}'}</span>, <span className="text-[#C9A84C]">{'{{dueDate}}'}</span>.
                                                        </p>
                                                        <button
                                                            type="submit"
                                                            disabled={submitting}
                                                            className="mt-4 inline-flex items-center gap-2 rounded-xl bg-[#C9A84C] px-5 py-3 text-sm font-semibold text-[#0A0F1E] transition hover:opacity-90 disabled:opacity-60"
                                                        >
                                                            <Send size={15} />
                                                            {submitting ? 'Creating campaign...' : 'Create campaign'}
                                                        </button>
                                                    </div>
                                                </form>
                                            </CollapsibleSection>
                                        </div>

                                        <AudiencePreview
                                            preview={preview}
                                            previewLoading={previewLoading}
                                            audienceType={form.audience_type}
                                        />
                                    </div>
                                </Surface>

                                <Surface className="rounded-3xl">
                                    <SectionHeader
                                        title="Saved manual campaigns"
                                        subtitle="Keep the finished campaigns here so the user sees one clean library instead of another dashboard."
                                    />
                                    <div className="space-y-4">
                                        {manualCampaigns.length ? manualCampaigns.map((campaign) => (
                                            <CampaignCard
                                                key={campaign.id}
                                                campaign={campaign}
                                                onToggle={toggleCampaign}
                                                onRun={runCampaign}
                                                runningCampaignId={runningCampaignId}
                                            />
                                        )) : <EmptyCard text="No manual campaigns yet. Create one above when you are ready." />}
                                    </div>
                                </Surface>
                            </div>

                            <div className="space-y-6">
                                <Surface className="rounded-3xl">
                                    <SectionHeader title="Simple workflow" subtitle="This side panel is now just a quick guide." />
                                    <div className="space-y-3">
                                        {[
                                            'Check the audience counts first.',
                                            'Leave the automatic campaigns running unless there is a reason to pause them.',
                                            'Use a manual campaign only for one-off pushes or event invites.',
                                        ].map((item) => (
                                            <div key={item} className="rounded-2xl bg-[#0D1526] p-4 text-sm leading-7 text-white/58">
                                                {item}
                                            </div>
                                        ))}
                                    </div>
                                </Surface>

                                <Surface className="rounded-3xl">
                                    <SectionHeader title="Recent activity" subtitle="Latest campaign runs for this dealership." />
                                    <div className="space-y-3">
                                        {(reactivation?.recent_runs || []).length === 0 ? (
                                            <EmptyCard text="No campaigns have been run yet. Use “Run now” on a campaign to create your first live test." />
                                        ) : (
                                            reactivation.recent_runs.map((run) => (
                                                <div key={run.id} className="rounded-2xl border border-white/10 bg-[#0D1526] p-4">
                                                    <div className="flex flex-wrap items-start justify-between gap-3">
                                                        <div>
                                                            <p className="text-sm font-semibold text-white">Campaign #{run.campaign_id}</p>
                                                            <p className="mt-1 text-sm text-white/45">{run.trigger_source}</p>
                                                        </div>
                                                        <p className="text-sm text-white/45">{new Date(run.created_at).toLocaleString()}</p>
                                                    </div>

                                                    <div className="mt-4 grid grid-cols-3 gap-3">
                                                        <div className="rounded-2xl bg-white/4 p-3 text-center">
                                                            <p className="text-xs text-white/45">Audience</p>
                                                            <p className="mt-2 text-lg font-black text-white">{run.audience_count}</p>
                                                        </div>
                                                        <div className="rounded-2xl bg-green-500/10 p-3 text-center">
                                                            <p className="text-xs text-green-300/75">Delivered</p>
                                                            <p className="mt-2 text-lg font-black text-green-300">{run.delivered_count}</p>
                                                        </div>
                                                        <div className="rounded-2xl bg-red-500/10 p-3 text-center">
                                                            <p className="text-xs text-red-300/75">Failed / skipped</p>
                                                            <p className="mt-2 text-lg font-black text-red-300">{(run.failed_count || 0) + (run.skipped_count || 0)}</p>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))
                                        )}
                                    </div>
                                </Surface>
                            </div>
                        </div>
                    </>
                )
            ) : null}

            {view === 'sequences' ? (
                <Surface className="rounded-3xl">
                    <SectionHeader
                        title="Sequences"
                        subtitle="These are your broader nurture flows. They stay separate from database reactivation so the page remains easier to use."
                    />

                    {loading ? (
                        <p className="text-sm text-white/40">Loading sequences...</p>
                    ) : (
                        <div className="space-y-4">
                            {sequences.map((sequence) => (
                                <div key={sequence.id} className={`overflow-hidden rounded-2xl border ${sequence.active ? 'border-[#C9A84C]/25 bg-[#121A2B]' : 'border-white/10 bg-[#121A2B]/70'}`}>
                                    <div className="flex cursor-pointer items-center justify-between p-5" onClick={() => setExpandedSeq(expandedSeq === sequence.id ? null : sequence.id)}>
                                        <div className="flex items-center gap-4">
                                            <button
                                                onClick={(event) => {
                                                    event.stopPropagation();
                                                    toggleSequence(sequence.id, sequence.active);
                                                }}
                                                className={sequence.active ? 'text-green-400' : 'text-white/30'}
                                            >
                                                {sequence.active ? <ToggleRight size={32} /> : <ToggleLeft size={32} />}
                                            </button>
                                            <div>
                                                <h3 className="font-outfit text-xl font-black text-white">{sequence.name}</h3>
                                                <p className="mt-1 text-sm text-white/45">Trigger: {sequence.trigger_type}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-4 text-white/50">
                                            <p className="text-sm">{sequence.steps?.length || 0} steps</p>
                                            {expandedSeq === sequence.id ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                                        </div>
                                    </div>

                                    {expandedSeq === sequence.id ? (
                                        <div className="border-t border-white/8 bg-[#0D1526] p-5">
                                            <div className="space-y-4">
                                                {sequence.steps?.map((step, index) => (
                                                    <div key={index} className="flex gap-4">
                                                        <div className="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full bg-white/8 text-sm font-semibold text-white">
                                                            {index + 1}
                                                        </div>
                                                        <div>
                                                            <p className="text-sm font-semibold text-white/70">
                                                                {step.day < 0 ? `Day ${step.day} before trigger` : `Day ${step.day}`}
                                                            </p>
                                                            <p className="mt-1 text-sm leading-7 text-white/55">{step.message}</p>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    ) : null}
                                </div>
                            ))}
                        </div>
                    )}
                </Surface>
            ) : null}

            {view === 'loyalty' && loyaltyData ? (
                <div className="space-y-6">
                    <div className="grid gap-4 md:grid-cols-3">
                        <StatCard icon={Heart} label="Net promoter score" value={loyaltyData.nps_data?.average_score} hint="Average customer sentiment after delivery." />
                        <StatCard icon={Crown} label="Loyalty tiers" value={loyaltyData.loyalty_tiers?.length || 0} hint="Tier structures available to the team." />
                        <StatCard icon={Gift} label="Points actions" value={loyaltyData.loyalty_points_awards?.length || 0} hint="Reward actions configured in the system." />
                    </div>

                    <div className="grid gap-6 xl:grid-cols-2">
                        <Surface className="rounded-3xl">
                            <SectionHeader title="Recent feedback" subtitle="Latest customer sentiment recorded in the system." />
                            <div className="space-y-3">
                                {loyaltyData.nps_data?.scores.map((score, index) => (
                                    <div key={index} className="flex items-center justify-between rounded-2xl bg-[#0D1526] p-4">
                                        <div>
                                            <p className="text-sm font-semibold text-white">{score.customer}</p>
                                            <p className="mt-1 text-sm text-white/48">{score.comment}</p>
                                        </div>
                                        <div className={`text-xl font-black ${score.score >= 9 ? 'text-green-400' : score.score >= 7 ? 'text-yellow-400' : 'text-red-400'}`}>
                                            {score.score}/10
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </Surface>

                        <Surface className="rounded-3xl">
                            <SectionHeader title="Tier benefits" subtitle="A simpler view of loyalty benefits by tier." />
                            <div className="grid gap-3 md:grid-cols-2">
                                {loyaltyData.loyalty_tiers?.map((tier, index) => (
                                    <div key={index} className="rounded-2xl bg-[#0D1526] p-4">
                                        <div className="flex items-end justify-between gap-3">
                                            <p className="text-lg font-black text-white">{tier.tier}</p>
                                            <p className="text-sm text-white/45">{tier.threshold}</p>
                                        </div>
                                        <p className="mt-2 text-sm leading-7 text-white/52">{tier.benefits}</p>
                                    </div>
                                ))}
                            </div>
                        </Surface>
                    </div>
                </div>
            ) : null}
        </PageShell>
    );
}

