                        </button>
                    </div>

                    <div className="luxury-card p-7" style={{ border: '1px solid rgba(201,168,76,0.15)' }}>
                        <div className="flex items-center gap-2 mb-4">
                            <CheckCircle2 size={16} className="text-[#C9A84C]" />
