/* ── Copy-to-clipboard utility ── */
function useCopy(text, timeout = 2000) {
    const [copied, setCopied] = useState(false);
    const copy = () => {
        navigator.clipboard.writeText(text).then(() => {
            setCopied(true);
            setTimeout(() => setCopied(false), timeout);
        });
    };
    return [copied, copy];
}

